    14	export const MAX_SUBMIT_ATTEMPTS = 5;
    15	
    16	/** True when retrying the same key + body is the only safe move. */
    17	export function isRetryableSubmitError(e: unknown): boolean {
    18	  // Unexpected (non-API) errors: we don't know what happened, so never treat as "not created".
    19	  if (!isApiError(e)) return true;
    20	  // 504/network, 429, 500/503, or a 2xx whose body we could not read (claim may exist).
    21	  return e.isUnknownOutcome || e.isTransient || e.code === 'BAD_RESPONSE';
    22	}
    23	
    24	/** 429 waits what the server asks; everything else backs off 1s, 2s, 4s, 8s (capped). */
    25	export function submitRetryDelayMs(attempt: number, e: unknown): number {
    26	  if (isApiError(e) && e.retryAfterMs != null) return e.retryAfterMs;
    27	  return Math.min(1000 * 2 ** attempt, 8000);
    28	}
