     8	 * A claim we created that the balances snapshot may not include yet.
     9	 * createdAt is the claim's server time, compared with the snapshot's asOf.
    10	 */
    11	export type PendingClaim = {
    12	  claimId: string;
    13	  asset: string;
    14	  amount: DecimalString;
    15	  createdAt: IsoDateString;
    16	};
    17	
    18	/** True while the snapshot predates the claim, i.e. the server numbers don't include it yet. */
    19	export function isNotInSnapshot(claim: PendingClaim, asOf: IsoDateString): boolean {
    20	  return Date.parse(asOf) <= Date.parse(claim.createdAt);
    21	}
    22	
    23	/**
    24	 * Balances as the user should see them: claims missing from the snapshot are
    25	 * moved from available to claiming, like the server will do on the next snapshot.
    26	 */
    27	export function applyPendingClaims<T extends Balance>(
    28	  items: readonly T[],
    29	  asOf: IsoDateString,
    30	  claims: readonly PendingClaim[],
    31	): T[] {
    32	  const open = claims.filter((c) => isNotInSnapshot(c, asOf));
    33	  if (open.length === 0) return [...items];
    34	  return items.map((b) => {
    35	    const amount = open
    36	      .filter((c) => c.asset === b.asset)
    37	      .reduce((sum, c) => sum.plus(new Big(c.amount)), ZERO);
    38	    if (amount.eq(ZERO)) return b;
    39	    const available = new Big(b.available).minus(amount);
