    42	      // Accruals/reversals between snapshots could make this dip below 0; never show negative.
    43	      available: toPlainString(available.lt(ZERO) ? ZERO : available),
    44	      claiming: toPlainString(new Big(b.claiming).plus(amount)),
    45	    };
    46	  });
