   128	export function formatUsd(value: AmountLike): string {
   129	  const v = toBig(value);
   130	  const fixed = v.abs().toFixed(2, Big.roundHalfUp);
   131	  const [intPart, frac] = fixed.split('.');
   132	  const body = `$${groupThousands(intPart)}.${frac}`;
   133	  return v.lt(ZERO) && fixed !== '0.00' ? `-${body}` : body;
