    14	export const MAX_SUBMIT_ATTEMPTS = 5;
    15	
    16	/** True when retrying the same key + body is the only safe move. */
    17	export function isRetryableSubmitError(e: unknown): boolean {
    18	  // Unexpected (non-API) errors: we don't know what happened, so never treat as "not created".
    19	  if (!isApiError(e)) return true;
    20	  // 504/network, 429, 500/503, or a 2xx whose body we could not read (claim may exist).
    21	  return e.isUnknownOutcome || e.isTransient || e.code === 'BAD_RESPONSE';
    22	}
    23	
    24	/** 429 waits what the server asks; everything else backs off 1s, 2s, 4s, 8s (capped). */
    25	export function submitRetryDelayMs(attempt: number, e: unknown): number {
    26	  if (isApiError(e) && e.retryAfterMs != null) return e.retryAfterMs;
    27	  return Math.min(1000 * 2 ** attempt, 8000);
    28	}
    29	
    30	/**
    31	 * Sends the same submission until it resolves or attempts run out.
    32	 * `send` must reuse submission.key: that is what makes the retries safe.
    33	 */
    34	export async function submitWithRetry(
    35	  submission: ClaimSubmission,
    36	  send: (s: ClaimSubmission) => Promise<Claim>,
    37	  sleep: (ms: number) => Promise<void> = (ms) => new Promise((r) => setTimeout(r, ms)),
    38	  maxAttempts = MAX_SUBMIT_ATTEMPTS,
    39	): Promise<SubmitResult> {
    40	  let lastError: unknown;
    41	  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    42	    if (attempt > 0) await sleep(submitRetryDelayMs(attempt - 1, lastError));
    43	    try {
    44	      return { kind: 'created', claim: await send(submission) };
    45	    } catch (e) {
    46	      if (!isRetryableSubmitError(e)) return { kind: 'rejected', error: e as ApiError };
    47	      lastError = e;
    48	    }
    49	  }
    50	  return { kind: 'unknown', error: lastError };
    51	}
