     4	export const TOKEN_STORAGE_KEY = 'cashmine.token';
     5	
     6	// Raw-string storage on top of localStorage (we ship a web build). Every access
     7	// is guarded: private mode / disabled storage must not crash the app, it just
     8	// means the token lives in memory for this session. On native there is no
     9	// localStorage, so the same in-memory fallback applies.
    10	// Same shape as jotai's (unexported) SyncStorage.
    11	type TokenStorage = {
    12	  getItem: (key: string, initialValue: string | null) => string | null;
    13	  setItem: (key: string, value: string | null) => void;
    14	  removeItem: (key: string) => void;
    15	};
    16	
    17	const memory = new Map<string, string>();
    18	
    19	function getLocalStorage(): Storage | null {
    20	  try {
    21	    return typeof localStorage === 'undefined' ? null : localStorage;
    22	  } catch {
    23	    return null;
    24	  }
    25	}
    26	
    27	const tokenStorage: TokenStorage = {
    28	  getItem(key, initialValue) {
    29	    try {
    30	      const value = getLocalStorage()?.getItem(key);
    31	      if (value) return value;
    32	    } catch {
    33	      // fall through to memory
    34	    }
    35	    return memory.get(key) ?? initialValue;
    36	  },
    37	  setItem(key, value) {
    38	    if (!value) return this.removeItem(key);
    39	    memory.set(key, value);
    40	    try {
    41	      getLocalStorage()?.setItem(key, value);
    42	    } catch {
    43	      // keep the in-memory copy only
    44	    }
    45	  },
    46	  removeItem(key) {
    47	    memory.delete(key);
    48	    try {
    49	      getLocalStorage()?.removeItem(key);
    50	    } catch {
    51	      // nothing else to clear
    52	    }
    53	  },
    54	};
    55	
    56	// null = no token yet. Read on init so the gate decides on the first render.
    57	export const tokenAtom = atomWithStorage<string | null>(TOKEN_STORAGE_KEY, null, tokenStorage, {
    58	  getOnInit: true,
    59	});
