  1	import { useQuery } from '@tanstack/react-query';
  2	import { Link, Stack, useLocalSearchParams } from 'expo-router';
  3	import { useSetAtom } from 'jotai';
  4	import { useEffect } from 'react';
  5	import { ActivityIndicator, Pressable, ScrollView, Text, View } from 'react-native';
  6	
  7	import { queryKeys, useBalances, useToken } from '@/api/queries';
  8	import { queryClient } from '@/api/query-client';
  9	import { getClaim } from '@/api/services';
 10	import { Row, styles } from '@/components/claim-ui';
 11	import { Colors } from '@/constants/theme';
 12	import { formatAmount } from '@/lib/amount';
 13	import { removePendingClaimAtom } from '@/state/pendingClaims';
 14	
 15	const POLL_MS = 2000;
 16	
 17	export default function ClaimStatusScreen() {
 18	  const { id } = useLocalSearchParams<{ id: string }>();
 19	  const token = useToken();
 20	  const removePendingClaim = useSetAtom(removePendingClaimAtom);
 21	  const balances = useBalances();
 22	  const claim = useQuery({
 23	    queryKey: queryKeys.claim(id),
 24	    queryFn: ({ signal }) => getClaim(token, id, signal),
 25	    refetchInterval: (q) => (q.state.data?.status === 'pending' ? POLL_MS : false),
 26	  });
 27	  const status = claim.data?.status;
 28	
 29	  useEffect(() => {
 30	    if (status !== 'completed' && status !== 'failed') return;
 31	    // Failed: the amount is available again. Completed stays in the overlay until a snapshot includes it.
 32	    if (status === 'failed') removePendingClaim(id);
 33	    void queryClient.invalidateQueries({ queryKey: queryKeys.balances });
 34	  }, [status, id, removePendingClaim]);
 35	
 36	  const header = <Stack.Screen options={{ title: 'Claim status' }} />;
 37	
 38	  if (!claim.data) {
 39	    return (
 40	      <View style={styles.center}>
 41	        {header}
 42	        {claim.isPending ? (
 43	          <ActivityIndicator size="large" color={Colors.primary} />
 44	        ) : (
 45	          <>
 46	            <Text style={styles.text}>{claim.error?.message ?? 'Could not load the claim.'}</Text>
 47	            <Pressable accessibilityRole="button" style={styles.button} onPress={() => claim.refetch()}>
 48	              <Text style={styles.buttonText}>Retry</Text>
 49	            </Pressable>
 50	          </>
 51	        )}
 52	      </View>
 53	    );
 54	  }
 55	
 56	  const c = claim.data;
 57	  // Decimals come from balances; until they load, show the server's strings as-is.
 58	  const decimals = balances.data?.items.find((b) => b.asset === c.asset)?.decimals;
 59	  const fmt = (v: string) => `${decimals == null ? v : formatAmount(v, decimals)} ${c.asset}`;
 60	  const statusColor =
 61	    c.status === 'completed' ? Colors.success : c.status === 'failed' ? Colors.danger : Colors.warning;
 62	
 63	  return (
 64	    <ScrollView style={styles.screen} contentContainerStyle={styles.content}>
 65	      {header}
 66	      <View style={styles.row}>
 67	        <Text style={styles.title}>{c.asset} claim</Text>
 68	        {c.status === 'pending' && <ActivityIndicator color={Colors.primary} />}
 69	      </View>
 70	      <Text style={[styles.title, { color: statusColor }]} accessibilityLiveRegion="polite">
 71	        {c.status === 'pending' ? 'Pending…' : c.status === 'completed' ? 'Completed' : 'Failed'}
 72	      </Text>
 73	      {c.status === 'failed' && (
 74	        <Text style={styles.error} accessibilityRole="alert">
 75	          {c.failureReason ?? 'The claim failed.'} The amount is back in your available balance.
 76	        </Text>
 77	      )}
 78	      <Row label="Amount" value={fmt(c.amount)} />
 79	      <Row label="Fee" value={fmt(c.fee)} />
 80	      <Row label="You receive" value={fmt(c.receiveAmount)} strong />
 81	      <Row label="Claim ID" value={c.id} />
 82	      {claim.isError && <Text style={styles.error}>Couldn&apos;t refresh the status. Retrying…</Text>}
 83	      <Link href="/" replace style={[styles.link, styles.centerText]}>
 84	        Back to balances
 85	      </Link>
 86	    </ScrollView>
 87	  );
 88	}

