  3	import type { ApiErrorBody } from './types';
  4	
  5	/** Server codes from the docs, plus client-side ones. */
  6	export type ApiErrorCodeOrClient =
  7	  | ApiErrorBody['error']['code']
  8	  | 'NETWORK' // request never got a response (offline, DNS, CORS, aborted)
  9	  | 'BAD_RESPONSE'; // response body was not the JSON we expected
 10	
 11	export class ApiError extends Error {
 12	  readonly status: number; // 0 when there was no HTTP response
 13	  readonly code: ApiErrorCodeOrClient;
 14	  readonly field?: string;
 15	  readonly retryAfterMs?: number;
 16	  readonly method: string;
 17	
 18	  constructor(opts: {
 19	    status: number;
 20	    code: ApiErrorCodeOrClient;
 21	    message: string;
 22	    method: string;
 23	    field?: string;
 24	    retryAfterMs?: number;
 25	  }) {
 26	    super(opts.message);
 27	    this.name = 'ApiError';
 28	    this.status = opts.status;
 29	    this.code = opts.code;
 30	    this.method = opts.method;
 31	    this.field = opts.field;
 32	    this.retryAfterMs = opts.retryAfterMs;
 33	  }
 34	
 35	  /** Token missing/invalid/expired: the UI should clear the token. */
 36	  get isUnauthorized(): boolean {
 37	    return this.status === 401 || this.code === 'UNAUTHORIZED';
 38	  }
 39	
 40	  /**
 41	   * For non-GET requests: the server may or may not have applied the request
 42	   * (504 TIMEOUT, or no response at all). Retry with the SAME idempotency key
 43	   * or poll; never treat this as "failed".
 44	   */
 45	  get isUnknownOutcome(): boolean {
 46	    if (this.method === 'GET') return false;
 47	    return this.status === 504 || this.code === 'TIMEOUT' || this.code === 'NETWORK';
 48	  }
 49	
 50	  /** Worth retrying automatically (for idempotent/GET requests). */
 51	  get isTransient(): boolean {
 52	    return (
 53	      this.code === 'NETWORK' ||
 54	      this.code === 'RATE_LIMITED' ||
 55	      this.code === 'SERVER' ||
