+async function hydrate() {
+  const [token, pending] = await Promise.all([
+    readItem(TOKEN_STORAGE_KEY, { secure: true }),
+    readItem(PENDING_CLAIMS_STORAGE_KEY),
+    hydrateSubmission(),
