cat > e2e/mock-api.ts <<'EOF'
import type { Page, Route } from '@playwright/test';

const CORS = {
  'access-control-allow-origin': '*',
  'access-control-allow-headers': 'Authorization, Content-Type, Idempotency-Key',
  'access-control-allow-methods': 'GET, POST, OPTIONS',
};

const now = () => new Date().toISOString();

export const balances = () => ({
  asOf: now(),
  items: [{ asset: 'USDT', decimals: 6, available: '100.5', pending: '1', claiming: '0', usdPrice: '1' }],
});

export const claimOptions = {
  asset: 'USDT',
  minAmount: '10',
  fee: '1.5',
  destinations: [{ id: 'dest_wallet', label: 'Wallet 0xabc' }],
};

export const claim = (status: 'pending' | 'completed') => ({
  id: 'clm_e2e',
  asset: 'USDT',
  amount: '20',
  fee: '1.5',
  receiveAmount: '18.5',
  destinationId: 'dest_wallet',
  status,
  failureReason: null,
  createdAt: now(),
  updatedAt: now(),
});

export type ClaimPost = { key: string | undefined; body: unknown };

/** Mocks the API; `postResponses` are answered in order for POST /v1/claims. */
export async function mockApi(page: Page, postResponses: { status: number; body: unknown }[] = []) {
  const posts: ClaimPost[] = [];
  await page.addInitScript(() => localStorage.setItem('cashmine.token', 'e2e-token'));
  await page.route('https://task-api.cashmine.io/**', async (route: Route) => {
    const req = route.request();
    const json = (status: number, body: unknown) =>
      route.fulfill({ status, headers: { ...CORS, 'content-type': 'application/json' }, body: JSON.stringify(body) });
    if (req.method() === 'OPTIONS') return route.fulfill({ status: 204, headers: CORS });
    const path = new URL(req.url()).pathname;
    if (path === '/v1/balances') return json(200, balances());
    if (path === '/v1/claim-options') return json(200, claimOptions);
    if (path === '/v1/activity') return json(200, { items: [], nextCursor: null });
    if (path === '/v1/claims' && req.method() === 'POST') {
      posts.push({ key: req.headers()['idempotency-key'], body: req.postDataJSON() });
      const next = postResponses[posts.length - 1] ?? { status: 201, body: claim('pending') };
      return json(next.status, next.body);
    }
    if (path.startsWith('/v1/claims/')) return json(200, claim('completed'));
    return json(404, { error: { code: 'NOT_FOUND', message: 'not mocked' } });
  });
  return posts;
}
EOF
cat > e2e/balances.e2e.ts <<'EOF'
import { expect, test } from '@playwright/test';

import { mockApi } from './mock-api';

test('shows balances and the USD total for a stored token', async ({ page }) => {
  await mockApi(page);
  await page.goto('/');

  await expect(page.getByText('$101.50')).toBeVisible();
  await expect(page.getByText('100.50', { exact: true })).toBeVisible();
});

test('asks for a token when none is stored', async ({ page }) => {
  await page.goto('/');

  await expect(page.getByText('Paste your API token to continue', { exact: false })).toBeVisible();
});
EOF
cat > e2e/claim.e2e.ts <<'EOF'
import { expect, test } from '@playwright/test';

import { claim, mockApi } from './mock-api';

const body = { asset: 'USDT', amount: '20', destinationId: 'dest_wallet' };

async function submitClaim(page: import('@playwright/test').Page) {
  await page.goto('/claim/USDT');
  await page.getByLabel('Amount in USDT').fill('20');
  await expect(page.getByText('18.50 USDT')).toBeVisible();
  await page.getByText('Review', { exact: true }).click();
  await page.getByText('Confirm', { exact: true }).click();
}

test('rejects an amount in a format the API does not accept', async ({ page }) => {
  await mockApi(page);
  await page.goto('/claim/USDT');

  await page.getByLabel('Amount in USDT').fill('05');

  await expect(page.getByText('Enter a number like 0.5.')).toBeVisible();
});

test('submits a claim and follows it until completed', async ({ page }) => {
  const posts = await mockApi(page);

  await submitClaim(page);

  await expect(page.getByText('Completed')).toBeVisible({ timeout: 10_000 });
  expect(posts).toHaveLength(1);
  expect(posts[0].body).toEqual(body);
  expect(posts[0].key).toBeTruthy();
});

test('retries a timed-out claim with the same idempotency key', async ({ page }) => {
  const posts = await mockApi(page, [
    { status: 504, body: { error: { code: 'TIMEOUT', message: 'timeout' } } },
    { status: 201, body: claim('pending') },
  ]);

  await submitClaim(page);

  await expect(page.getByText('Completed')).toBeVisible({ timeout: 10_000 });
  expect(posts).toHaveLength(2);
  expect(posts[1].key).toBe(posts[0].key);
  expect(posts[1].body).toEqual(posts[0].body);
});
EOF
